-- 홈 배너 인사이트 문구(힐링/명언/기능가이드/통계템플릿) -- 2026-08-01 사용자 지시("출시전에", 백엔드로 이전).
-- 예전엔 src/services/insightContent.ts에 하드코딩돼 있어서 문구 하나 고치려면 앱스토어 재배포가
-- 필요했다. 이 테이블로 옮겨서 SQL만 바꾸면 앱 업데이트 없이 문구를 추가/수정/비활성화할 수 있다.
-- category: healing | quote | tip | stat_yesterdayLastWatched | stat_todayMoreThanAvg | stat_todayLessThanAvg
-- stat_* 세 카테고리는 {{time}}/{{diff}} 플레이스홀더를 포함하며 클라이언트가 실제 값으로 치환한다.
CREATE TABLE insight_item (
    id         BIGINT AUTO_INCREMENT PRIMARY KEY,
    category   VARCHAR(32)  NOT NULL,
    text_en    VARCHAR(500) NOT NULL,
    text_ko    VARCHAR(500) NOT NULL,
    active     BOOLEAN      NOT NULL DEFAULT TRUE,
    created_at DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX idx_insight_item_category ON insight_item (category, active);

